entries.command:
app.example.com {
  reverse_proxy localhost:3000
}
api.example.com {
  reverse_proxy localhost:8080
}

example.com {
  handle /api/* {
    reverse_proxy localhost:8080
  }
  handle {
    root * /var/www/html
    file_server
  }
}

caddy hash-password
# Then in Caddyfile:
basicauth /admin/* {
  admin $2a$14$...
}

example.com {
  header {
    X-Frame-Options DENY
    X-Content-Type-Options nosniff
    -Server
  }
  reverse_proxy localhost:8080
}
